co<-c('LN','HN','LU','HU','LA','HA');cols<-paper_style$condition;shapes<-c(LN=1,HN=16,LU=2,HU=17,LA=0,HA=15);ltys<-c(LN='dashed',HN='solid',LU='dashed',HU='solid',LA='dashed',HA='solid')
ptime<-function(dat,yl){ggplot(dat,aes(day,mean,colour=condition,shape=condition,linetype=condition,group=condition))+geom_line(linewidth=.65)+geom_errorbar(aes(ymin=mean-se,ymax=mean+se),width=.17,linewidth=.4,linetype='solid',show.legend=FALSE)+geom_point(size=2,stroke=.55)+scale_colour_manual(values=cols,breaks=co)+scale_shape_manual(values=shapes,breaks=co)+scale_linetype_manual(values=ltys,breaks=co)+scale_x_continuous(breaks=sort(unique(dat$day)),limits=c(min(dat$day)-.35,max(dat$day)+.35),expand=c(0,0))+labs(x='Time (d)',y=yl,colour=NULL,shape=NULL,linetype=NULL)+base_theme()+theme(legend.position='top',legend.text=element_text(size=8.5),legend.key.width=unit(9,'mm'),plot.margin=margin(8,8,8,8))}
